import sys, os, struct; sys.path.insert(0,'/tmp/h')
from probe import *
from dnsbuild import *

def mk(qname, qtype, answers=(), auths=(), adds=()):
    b = hdr(an=len(answers), ns=len(auths), ar=len(adds)) + question(qname, qtype)
    for a in list(answers)+list(auths)+list(adds): b += a
    return b

# two queries: two domains
def respfn(req, i):
    qn = ['aaa.example.com','b.io'][i]
    if i==0:
        return mk(qn,1,[rr(qn,1,1,300,bytes([1,2,3,4]))])
    else:
        return mk(qn,1,[rr(qn,1,1,86400,bytes([9,9,9,9]))])
out,err,rc,reqs = run(['aaa.example.com','b.io','-n','127.0.0.1:@PORT@'], respfn, count=2)
print("2 domains:", repr(out.decode()), rc, err)

# two types on one domain
def respfn2(req, i):
    if i==0: return mk('e.net',1,[rr('e.net',1,1,60,bytes([1,2,3,4]))])
    else: return mk('e.net',15,[rr('e.net',15,1,7200,struct.pack('!H',10)+name('mail.e.net'))])
out,err,rc,reqs = run(['e.net','A','MX','-n','127.0.0.1:@PORT@'], respfn2, count=2)
print("2 types:", repr(out.decode()), rc, err)
EOF
