import sys, os, struct, random; sys.path.insert(0,'/tmp/h')
from probe import *
from dnsbuild import *
def dur(s):
    if s>=86400:
        d,r=divmod(s,86400);h,r=divmod(r,3600);m,x=divmod(r,60); return "%dd%dh%02dm%02ds"%(d,h,m,x)
    if s>=3600:
        h,r=divmod(s,3600);m,x=divmod(r,60); return "%dh%02dm%02ds"%(h,m,x)
    if s>=60:
        m,x=divmod(s,60); return "%dm%02ds"%(m,x)
    return "%ds"%s
random.seed(3)
vals = set()
for b in [0,1,59,60,61,3599,3600,3601,86399,86400,86401,90000,604800,1000000,31536000,4294967295]:
    for d in (-2,-1,0,1,2): 
        v=b+d
        if 0<=v<=4294967295: vals.add(v)
for k in range(0,32):
    for d in (-1,0,1):
        v=(1<<k)+d
        if 0<=v<=4294967295: vals.add(v)
for h in range(0,24):
    vals.add(86400+h*3600); vals.add(86400*9+h*3600+61); vals.add(86400*11+h*3600)
for m in range(0,60): vals.add(3600+m*60+7); vals.add(m*60+3)
for s in range(0,60): vals.add(86400*3+3600*5+60*7+s)
for _ in range(600): vals.add(random.randint(0,4294967295))
vals = sorted(vals)
print("testing", len(vals), "values")
fails=0
B=90
for i in range(0,len(vals),B):
    batch=vals[i:i+B]
    recs=b''.join(rr('e.net',1,1,v,bytes([1,2,3,4])) for v in batch)
    resp=hdr(an=len(batch))+question('e.net',1)+recs
    out,err,rc,_=run(['e.net','-n','127.0.0.1:@PORT@','-T'],resp,tcp=True)
    lines=out.decode().split('\n')[:-1]
    assert len(lines)==len(batch), (len(lines),len(batch),rc,err[:200])
    w=max(len(dur(v)) for v in batch)
    for v,l in zip(batch,lines):
        exp='A e.net. '+dur(v).rjust(w)+'   1.2.3.4'
        if l!=exp:
            fails+=1
            if fails<20: print("MISMATCH v=%d exp=%r got=%r"%(v,exp,l))
print("fails",fails)
EOF
